using System.Drawing;
using System.Drawing.Imaging;
using ShadowUse.Capture;
using ShadowUse.Native;
using Windows.Graphics.Imaging;
using Windows.Media.Ocr;
using Windows.Storage.Streams;

namespace ShadowUse.Vision;

/// <summary>F05 visual-grounding fallback: OCR-based text region detection using the
/// OS-provided Windows.Media.Ocr engine (no downloaded model, no new dependency — the
/// projections are generated by the SDK-style Windows TFM). Invoked only by the caller when
/// structured UIA evidence is inadequate (see ComputerUseTools.GetAppState); this service
/// never decides that on its own. Perception is kept separate from execution: this class only
/// produces candidates and re-validates geometry, it never dispatches input.</summary>
internal static class VisualGroundingService
{
    private static readonly object EngineLock = new();
    private static bool _engineInitialized;
    private static OcrEngine? _engine;

    // Below this Hamming distance out of 64 dHash bits, two captures of the same bbox are
    // treated as "the same region" (tolerates anti-aliasing/caret-blink noise, not a real
    // content change). Chosen conservatively small relative to the 64-bit hash.
    private const int RegionHashToleranceBits = 6;

    internal static OcrEngine? GetEngineLazy()
    {
        lock (EngineLock)
        {
            if (!_engineInitialized)
            {
                _engine = OcrEngine.TryCreateFromUserProfileLanguages();
                _engineInitialized = true;
            }
            return _engine;
        }
    }

    public static async Task<VisualGroundingOutcome> RecognizeAsync(IntPtr hwnd, CancellationToken ct)
    {
        var engine = GetEngineLazy();
        if (engine == null)
            return VisualGroundingOutcome.Unsupported(
                "No OCR language is installed for this system (OcrEngine.TryCreateFromUserProfileLanguages returned null).");

        var capture = ScreenshotService.CaptureWindowForVision(hwnd);
        if (capture == null)
            return VisualGroundingOutcome.Unsupported("Window capture failed (PrintWindow returned no usable content).");

        var (bitmap, windowRect) = capture.Value;
        try
        {
            ct.ThrowIfCancellationRequested();
            using var softwareBitmap = await ToSoftwareBitmapAsync(bitmap).ConfigureAwait(false);
            var ocrResult = await engine.RecognizeAsync(softwareBitmap);

            var rawLines = ocrResult.Lines
                .Select(line => (Text: line.Text?.Trim() ?? "", Rect: UnionRect(line.Words)))
                .Where(l => l.Text.Length > 0 && l.Rect.Width > 0 && l.Rect.Height > 0)
                .ToList();

            var textCounts = rawLines
                .GroupBy(l => l.Text, StringComparer.OrdinalIgnoreCase)
                .ToDictionary(g => g.Key, g => g.Count(), StringComparer.OrdinalIgnoreCase);

            var candidates = new List<VisualCandidate>();
            int i = 0;
            foreach (var line in rawLines)
            {
                i++;
                bool unique = textCounts[line.Text] == 1;
                candidates.Add(new VisualCandidate
                {
                    Id = $"v{i}",
                    Text = line.Text,
                    X = line.Rect.X,
                    Y = line.Rect.Y,
                    Width = line.Rect.Width,
                    Height = line.Rect.Height,
                    ScreenX = windowRect.Left + line.Rect.X,
                    ScreenY = windowRect.Top + line.Rect.Y,
                    Confidence = unique ? 1.0 : 0.5,
                    ConfidenceSource = "uniqueness_heuristic",
                    RegionHash = RegionHash.Compute(bitmap, line.Rect),
                });
            }

            var observation = new VisualObservation
            {
                CapturedAtUtc = DateTimeOffset.UtcNow,
                WindowRectAtCapture = windowRect,
                DpiAtCapture = NativeMethods.GetDpiForWindow(hwnd),
                ParserId = "windows.media.ocr",
                ParserVersion = $"{Environment.OSVersion.Version} / {engine.RecognizerLanguage.LanguageTag}",
                Candidates = candidates,
            };
            return VisualGroundingOutcome.Success(observation);
        }
        finally
        {
            bitmap.Dispose();
        }
    }

    /// <summary>Re-validates a candidate against the live window before it is turned into a
    /// click: geometry (position/size), DPI, and a fresh region-hash of just the candidate's
    /// bbox must all match closely enough. Any mismatch means "reobserve", never a guessed
    /// click against stale geometry (F05-T02).</summary>
    public static async Task<(bool Ok, string? Reason)> TryRevalidateAsync(
        IntPtr hwnd,
        VisualObservation observation,
        VisualCandidate candidate,
        CancellationToken ct)
    {
        if (!NativeMethods.IsWindow(hwnd))
            return (false, "Target window no longer exists.");
        if (!NativeMethods.GetWindowRect(hwnd, out var currentRect))
            return (false, "Target window bounds could not be read.");
        var original = observation.WindowRectAtCapture;
        if (currentRect.Left != original.Left || currentRect.Top != original.Top
            || currentRect.Right != original.Right || currentRect.Bottom != original.Bottom)
            return (false, "Window moved or resized since the visual observation was captured.");

        uint currentDpi = NativeMethods.GetDpiForWindow(hwnd);
        if (currentDpi != observation.DpiAtCapture)
            return (false, "Window DPI changed since the visual observation was captured.");

        ct.ThrowIfCancellationRequested();
        var recapture = ScreenshotService.CaptureWindowForVision(hwnd);
        if (recapture == null)
            return (false, "Recapture failed while re-validating the visual observation.");

        try
        {
            var region = new Rectangle(candidate.X, candidate.Y, candidate.Width, candidate.Height);
            var freshHash = RegionHash.Compute(recapture.Value.Bitmap, region);
            if (RegionHash.HammingDistance(candidate.RegionHash, freshHash) > RegionHashToleranceBits)
                return (false, "The captured region's pixels changed since the visual observation.");
            return (true, null);
        }
        finally
        {
            recapture.Value.Bitmap.Dispose();
        }
    }

    private static Rectangle UnionRect(IReadOnlyList<OcrWord> words)
    {
        if (words.Count == 0) return Rectangle.Empty;
        double left = double.MaxValue, top = double.MaxValue, right = double.MinValue, bottom = double.MinValue;
        foreach (var w in words)
        {
            var r = w.BoundingRect;
            left = Math.Min(left, r.X);
            top = Math.Min(top, r.Y);
            right = Math.Max(right, r.X + r.Width);
            bottom = Math.Max(bottom, r.Y + r.Height);
        }
        return Rectangle.FromLTRB((int)left, (int)top, (int)Math.Ceiling(right), (int)Math.Ceiling(bottom));
    }

    private static async Task<SoftwareBitmap> ToSoftwareBitmapAsync(Bitmap bitmap)
    {
        using var ms = new MemoryStream();
        bitmap.Save(ms, ImageFormat.Png);
        ms.Position = 0;

        using var randomAccessStream = new InMemoryRandomAccessStream();
        using (var outputStream = randomAccessStream.GetOutputStreamAt(0))
        {
            using var writer = new DataWriter(outputStream);
            writer.WriteBytes(ms.ToArray());
            await writer.StoreAsync();
            await writer.FlushAsync();
            writer.DetachStream();
        }
        randomAccessStream.Seek(0);

        var decoder = await BitmapDecoder.CreateAsync(randomAccessStream);
        return await decoder.GetSoftwareBitmapAsync(BitmapPixelFormat.Bgra8, BitmapAlphaMode.Premultiplied);
    }
}
